head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsStrtDt = ""; // 조회조건 결산일자 FROM
scwin.vAcntclsEndDt = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 조회조건 결산일자 TO

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init = async function() {
    // 결산일자 조회
    // 결산일자 From To 변경
    // frame.Provider("../frame_head").fn_SrchAcntclsDt();

    await scwin.search();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_MngAdmCompst_OnLoadError
 * @description dts_MngAdmCompst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_MngAdmCompst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_MngAdmCompst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00219.dts_MngAdmCompst_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_MngAdmCompst_OnLoadCompleted
 * @description dts_MngAdmCompst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_MngAdmCompst_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_MngAdmCompst.errorMsg) {
            alert(dts_MngAdmCompst.errorMsg);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00219.dts_MngAdmCompst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_MngAdmCompst_OnDblClick
 * @description grd_MngAdmCompst 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_MngAdmCompst_OnDblClick = function(row, colid) {
    try {
        if (colid === "NM") {
            // 경영자상세조회 팝업 오픈

            // fn_MngAdmDtlSrchOpen();

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00219.grd_MngAdmCompst_OnDblClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 경영진구성 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_MngAdmCompst",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_MngAdmCompst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_MngAdmCompst.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.

    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

    scwin.vAcntclsStrtDt = $c.frame.path("../frame_head").fn_GetAcntclsStrtDt();

    scwin.vAcntclsEndDt = $c.frame.path("../frame_head").fn_GetAcntclsEndDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsStrtDt === "" || scwin.vAcntclsEndDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name mngAdmDtlSrchOpen
 * @description 경영진상세조회 팝업
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.mngAdmDtlSrchOpen = async function() {
    fn_GetPar = scwin.getParKey;
    const options = {
        id: "ULDFIS00200_P1",
        title: "인물 검색",
        type: "browserPopup",
        width: 590 + 20,
        height: 377 + 45,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("./ULDFIS00200_P1.gfm", options);
};

/**
 * @method
 * @name getParKey
 * @description 팝업으로 값을 넘김.
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParKey = function(arrPar) {
    const nRow = dts_MngAdmCompst.getRowPosition();
    arrPar[0] = dts_MngAdmCompst.getCellData(nRow, "PERSON_CD");
    arrPar[1] = dts_MngAdmCompst.getCellData(nRow, "KIS_CD");
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 */
scwin.excelDownload = function() {
    if (dts_MngAdmCompst.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_MngAdmCompst, {fileName: "경영진구성", type: "1"});
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    await scwin.init();
};
